/** A measured disclosure that stays mounted through polling and dismissal. */
export default function DisclosurePopover({ open, onClose, trigger, id, label, className, children }: {
  open: boolean; onClose: () => void; trigger: RefObject<HTMLButtonElement>;
  id: string; label: string; className: string; children: ReactNode;
}) {
  const panel = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !open);
    const finish = () => { element.style.height = open ? "auto" : "0px"; element.style.opacity = open ? "1" : "0"; };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    element.style.height = `${element.getBoundingClientRect().height}px`;
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = open ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = open ? "1" : "0";
      timeout = window.setTimeout(finish, 200);
    });
    const transitioned = (event: TransitionEvent) => { if (event.target === element && event.propertyName === "height") finish(); };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [open]);
  useEffect(() => {
    if (!open) return;
    const dismiss = () => { onClose(); trigger.current?.focus(); };
    const pointer = (event: PointerEvent) => {
      if (event.target instanceof Node && !panel.current?.contains(event.target) && !trigger.current?.contains(event.target)) onClose();
    };
    const key = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); dismiss(); } };
    document.addEventListener("pointerdown", pointer);
    document.addEventListener("keydown", key);
    return () => { document.removeEventListener("pointerdown", pointer); document.removeEventListener("keydown", key); };
  }, [open, onClose, trigger]);
  return <div ref={panel} id={id} className={`disclosure-popover ${className}`} role="dialog" aria-label={label} aria-hidden={!open}>
    <div className="popover-surface">{children}</div>
  </div>;
}

import { useLayoutEffect, useRef, useState, type ReactNode } from "react";

/** Keep native summary keyboard semantics, and retain the subtree through collapse. */
export default function AnimatedDetails({ className, summary, summaryLabel, summaryTitle, scrollKey, initialExpanded = false, onExpandedChange, children, onInspect }: {
  className: string; summary: ReactNode; summaryLabel?: string; summaryTitle?: string; scrollKey?: string;
  initialExpanded?: boolean; onExpandedChange?: (expanded: boolean) => void; children: ReactNode; onInspect: () => void;
}) {
  const [expanded, setExpanded] = useState(initialExpanded);
  const [present, setPresent] = useState(initialExpanded);
  const initial = useRef(initialExpanded);
  const animatedExpanded = useRef(initialExpanded);
  const desired = useRef(initialExpanded);
  const panel = useRef<HTMLDivElement>(null);

  // Depend only on user expansion. Polling must not restart animations or move scroll positions.
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !expanded);
    // A regrouped event restores its measured-open state without replaying an animation.
    if (animatedExpanded.current === expanded) return;
    animatedExpanded.current = expanded;
    const finish = () => {
      element.style.height = desired.current ? "auto" : "0px";
      element.style.opacity = desired.current ? "1" : "0";
      if (!desired.current) setPresent(false);
    };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    const height = element.getBoundingClientRect().height;
    const opacity = getComputedStyle(element).opacity;
    element.style.height = `${height}px`;
    element.style.opacity = opacity;
    // Establish the current rendered height before transitioning to the measured target.
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = expanded ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = expanded ? "1" : "0";
      const seconds = Number.parseFloat(getComputedStyle(element).getPropertyValue("--transition-duration-basic")) || .15;
      timeout = window.setTimeout(finish, seconds * 1000 + 50);
    });
    const transitioned = (event: TransitionEvent) => {
      if (event.target === element && event.propertyName === "height") finish();
    };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [expanded]);

  return <details className={className} data-scroll-key={scrollKey} open={present}>
    <summary aria-label={summaryLabel} aria-expanded={expanded} title={summaryTitle || undefined} onClick={(event) => {
      event.preventDefault();
      onInspect();
      desired.current = !desired.current;
      onExpandedChange?.(desired.current);
      setPresent(true);
      setExpanded(desired.current);
    }}>{summary}</summary>
    <div ref={panel} className="detail-collapsible" style={{ height: initial.current ? "auto" : "0px", opacity: initial.current ? 1 : 0 }}>{children}</div>
  </details>;
}

import { useEffect, useRef, useState } from "react";
import { request, type Connection } from "./api";
import { errorMessage } from "./logic";
import { statusLabel } from "./presentation";

export interface WorkerRun {
  run_id: string;
  worker_id?: string;
  quest_id?: string;
  role?: string;
  state?: string;
  provider_id?: string;
  model_id?: string;
  steps?: number;
  tool_spent?: number;
  created_at?: string;
  output_contract?: string;
}

export interface ActivityState {
  items: WorkerRun[];
  loading: boolean;
  error: string;
  hasMore: boolean;
  connected: boolean;
}

interface ActivityPage { items: WorkerRun[]; has_more?: boolean }
interface ActivitySnapshot { identity: string; state: ActivityState }

const emptyActivity = (connected: boolean): ActivityState => ({
  items: [], loading: connected, error: "", hasMore: false, connected,
});
const connectionIdentity = (connection: Connection | null) => connection
  ? `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}` : "";

/** This read-only feed runs independently so a slow activity request cannot delay chat. */
export function useWorkerActivity(connection: Connection | null): ActivityState {
  const identity = connectionIdentity(connection);
  const currentIdentity = useRef(identity);
  currentIdentity.current = identity;
  const [snapshot, setSnapshot] = useState<ActivitySnapshot>(() => ({ identity, state: emptyActivity(!!connection) }));

  useEffect(() => {
    if (!connection) {
      setSnapshot({ identity, state: emptyActivity(false) });
      return;
    }
    let active = true;
    let inFlight = false;
    let controller: AbortController | null = null;
    setSnapshot({ identity, state: emptyActivity(true) });
    const accepts = () => active && currentIdentity.current === identity;
    const poll = async () => {
      if (!accepts() || inFlight) return;
      inFlight = true;
      const pending = new AbortController();
      controller = pending;
      const timeout = window.setTimeout(() => pending.abort(), 120000);
      try {
        const page = await request<ActivityPage>(connection, "/api/activity?limit=100", { signal: pending.signal });
        if (!Array.isArray(page.items)) throw new Error("Core 返回了无效执行记录。");
        const items = [...new Map(page.items.filter((item) => item && typeof item === "object" && typeof item.run_id === "string" && item.run_id)
          .map((item) => [item.run_id, item])).values()];
        if (accepts()) setSnapshot({ identity, state: { items, loading: false, error: "", hasMore: page.has_more === true, connected: true } });
      } catch (error) {
        // Old running states must never be presented as the current state after a failed read.
        if (accepts()) setSnapshot({ identity, state: { items: [], loading: false, error: errorMessage(error), hasMore: false, connected: true } });
      } finally {
        window.clearTimeout(timeout);
        if (controller === pending) controller = null;
        inFlight = false;
      }
    };
    void poll();
    const timer = window.setInterval(() => void poll(), 6000);
    return () => { active = false; window.clearInterval(timer); controller?.abort(); };
  }, [identity, connection?.bearer]);

  // Hide a previous workspace synchronously, before the effect starts its next request.
  return snapshot.identity === identity ? snapshot.state : emptyActivity(!!connection);
}

const field = (value: unknown, fallback: string) => typeof value === "string" && value ? value : fallback;
const RUN_PRIORITY: Record<string, number> = { running: 0, blocked: 1, queued: 2, review_pending: 3, paused: 4 };
const priority = (run: WorkerRun) => RUN_PRIORITY[field(run.state, "")] ?? 5;

export default function WorkerActivity({ state, quests, onQuest, onActivity }: {
  state: ActivityState;
  quests: { id: string; title: string }[];
  onQuest: (id: string) => void;
  onActivity: () => void;
}) {
  const visible = state.connected && !state.error ? [...state.items].sort((left, right) => priority(left) - priority(right)).slice(0, 3) : [];
  const notice = !state.connected ? "连接 Core 后查看执行记录" : state.loading ? "正在读取执行记录…"
    : state.error ? "执行状态暂不可用" : !state.items.length ? "暂无执行记录" : "";
  const summary = `最近执行${state.connected && !state.loading && !state.error ? ` · 已加载 ${state.items.length} 条${state.hasMore ? " · 还有更早记录" : ""}` : ""}`;
  return <section className="worker-activity" aria-label="Worker 执行记录" aria-busy={state.loading}>
    <div className="worker-activity-header"><div className="worker-activity-heading"><strong>Worker</strong><small title={summary}>{summary}</small></div>
      <button type="button" className="text-button worker-activity-open" disabled={!state.connected} onClick={onActivity}>查看运行活动</button>
    </div>
    {notice && <p className="worker-activity-notice" title={state.error || undefined}>{notice}</p>}
    {visible.length > 0 && <div className="worker-activity-list">{visible.map((run) => {
      const quest = quests.find((item) => item.id === run.quest_id);
      const model = field(run.model_id, "模型未记录");
      const title = `角色：${field(run.role, "未记录")}\n供应商：${field(run.provider_id, "未记录")}\n模型：${model}\nWorker：${field(run.worker_id, "未记录")}\nRun：${run.run_id}\n任务：${quest?.title || field(run.quest_id, "未记录")}`;
      const content = <><span className="worker-run-content"><span className="worker-run-heading"><strong>{field(run.role, "Worker")}</strong><span className="worker-run-model">{model}</span></span><span className="worker-run-quest">{quest?.title || "关联任务未加载"}</span></span>
        <span className="worker-run-state" data-state={field(run.state, "unknown")}>{statusLabel(run.state)}</span></>;
      return quest ? <button type="button" className="worker-run" key={run.run_id} title={title} onClick={() => onQuest(quest.id)}>{content}</button>
        : <div className="worker-run" key={run.run_id} title={title}>{content}</div>;
    })}</div>}
  </section>;
}

