//! Bounded, read-only file inspection scoped to the Core host's immutable workspace root.
use serde::Serialize;
use std::fs::{self, File};
use std::io::Read;
use std::path::{Component, Path, PathBuf};
use std::process::{Command, Output, Stdio};
use std::sync::mpsc;
use std::thread;
use std::time::{Duration, Instant, UNIX_EPOCH};

const FILE_LIMIT: u64 = 24 * 1024 * 1024;
const TEXT_LIMIT: u64 = 2 * 1024 * 1024;
const GIT_LIMIT: usize = 4 * 1024 * 1024;
const ENTRY_LIMIT: usize = 5000;

#[derive(Serialize)]
pub struct WorkspaceFile {
    path: String,
    name: String,
    directory: bool,
    size: u64,
    modified: Option<u64>,
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FileChange {
    path: String,
    status: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    previous_path: Option<String>,
}
#[derive(Serialize)]
pub struct ChangeSet {
    files: Vec<FileChange>,
    repository: bool,
    truncated: bool,
}
#[derive(Serialize)]
pub struct WorkspaceDocument {
    path: String,
    kind: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    text: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    bytes: Option<Vec<u8>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    mime: Option<String>,
    size: u64,
    modified: Option<u64>,
}
#[derive(Serialize)]
pub struct FileDiff {
    text: String,
    binary: bool,
    truncated: bool,
}

fn relative(value: &str, allow_empty: bool) -> Result<PathBuf, String> {
    if value.is_empty() && allow_empty {
        return Ok(PathBuf::new());
    }
    if value.is_empty() || value.len() > 4096 || value.chars().any(|c| c.is_control() || c == ':') {
        return Err("文件路径不在当前工作空间中。".into());
    }
    let normalized = value.replace('\\', "/");
    if normalized.split('/').any(|part| part.is_empty() || part == "." || part == "..") {
        return Err("文件路径不在当前工作空间中。".into());
    }
    let path = PathBuf::from(normalized);
    if path.components().any(|part| !matches!(part, Component::Normal(_))) {
        return Err("文件路径不在当前工作空间中。".into());
    }
    Ok(path)
}

fn root_path(root: &Path) -> Result<PathBuf, String> {
    fs::canonicalize(root).map_err(|_| "当前工作空间目录不可用。".into())
}

fn is_link(metadata: &fs::Metadata) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        metadata.file_attributes() & 0x400 != 0
    }
    #[cfg(not(windows))]
    metadata.file_type().is_symlink()
}

fn resolve(root: &Path, value: &str, allow_empty: bool, allow_missing: bool) -> Result<PathBuf, String> {
    let relative = relative(value, allow_empty)?;
    let canonical_root = root_path(root)?;
    let mut candidate = canonical_root.clone();
    for part in relative.components() {
        candidate.push(part.as_os_str());
        match fs::symlink_metadata(&candidate) {
            Ok(metadata) if is_link(&metadata) => return Err("不能预览符号链接或重解析目录。".into()),
            Ok(_) => {}
            Err(error) if allow_missing && error.kind() == std::io::ErrorKind::NotFound => {}
            Err(_) => return Err("文件或目录不可用。".into()),
        }
    }
    let existing = if candidate.exists() { candidate.as_path() } else {
        candidate.ancestors().find(|path| path.exists()).ok_or("文件路径不可用。")?
    };
    if !fs::canonicalize(existing).map_err(|_| "文件路径不可用。")?.starts_with(&canonical_root) {
        return Err("文件路径不在当前工作空间中。".into());
    }
    Ok(candidate)
}

fn modified(metadata: &fs::Metadata) -> Option<u64> {
    metadata.modified().ok()?.duration_since(UNIX_EPOCH).ok().map(|value| value.as_millis() as u64)
}

fn path_text(path: &Path) -> Result<String, String> {
    path.to_str().map(|value| value.replace('\\', "/")).ok_or("此文件名不是有效 Unicode。".into())
}

pub fn list(root: &Path, path: &str) -> Result<Vec<WorkspaceFile>, String> {
    let directory = resolve(root, path, true, false)?;
    if !directory.is_dir() { return Err("此路径不是目录。".into()); }
    let mut files = Vec::new();
    let canonical_root = root_path(root)?;
    for entry in fs::read_dir(directory).map_err(|_| "无法读取工作空间目录。")? {
        let entry = entry.map_err(|_| "无法读取目录项目。")?;
        let metadata = fs::symlink_metadata(entry.path()).map_err(|_| "无法读取文件信息。")?;
        if is_link(&metadata) { continue; }
        if files.len() >= ENTRY_LIMIT { return Err("此目录超过 5000 项，请打开更具体的子目录。".into()); }
        let relative = path_text(entry.path().strip_prefix(&canonical_root).map_err(|_| "目录越过工作空间边界。")?)?;
        files.push(WorkspaceFile { path: relative, name: entry.file_name().to_string_lossy().into_owned(), directory: metadata.is_dir(), size: metadata.len(), modified: modified(&metadata) });
    }
    files.sort_by(|a, b| b.directory.cmp(&a.directory).then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase())));
    Ok(files)
}

fn opened_in_workspace(file: &File, root: &Path) -> Result<(), String> {
    #[cfg(windows)]
    {
        use std::ffi::OsString;
        use std::os::windows::ffi::OsStringExt;
        use std::os::windows::io::AsRawHandle;
        #[link(name = "kernel32")]
        extern "system" { fn GetFinalPathNameByHandleW(handle: *mut std::ffi::c_void, path: *mut u16, size: u32, flags: u32) -> u32; }
        let mut buffer = vec![0_u16; 32768];
        let length = unsafe { GetFinalPathNameByHandleW(file.as_raw_handle(), buffer.as_mut_ptr(), buffer.len() as u32, 0) } as usize;
        if length == 0 || length >= buffer.len() { return Err("无法验证文件的工作空间范围。".into()); }
        let final_path = PathBuf::from(OsString::from_wide(&buffer[..length]));
        if !final_path.starts_with(root_path(root)?) { return Err("文件路径不在当前工作空间中。".into()); }
    }
    #[cfg(not(windows))]
    { let _ = (file, root); }
    Ok(())
}

pub fn read(root: &Path, path: &str) -> Result<WorkspaceDocument, String> {
    let resolved = resolve(root, path, false, false)?;
    let mut file = File::open(&resolved).map_err(|_| "无法打开文件。")?;
    opened_in_workspace(&file, root)?;
    let metadata = file.metadata().map_err(|_| "无法读取文件信息。")?;
    if !metadata.is_file() { return Err("此路径不是普通文件。".into()); }
    if metadata.len() > FILE_LIMIT { return Err("文件超过 24 MB 预览上限。".into()); }
    let extension = resolved.extension().and_then(|value| value.to_str()).unwrap_or("").to_ascii_lowercase();
    let mime = match extension.as_str() {
        "pdf" => Some("application/pdf"), "png" => Some("image/png"), "jpg" | "jpeg" => Some("image/jpeg"),
        "gif" => Some("image/gif"), "webp" => Some("image/webp"), "avif" => Some("image/avif"), "bmp" => Some("image/bmp"), _ => None,
    };
    let unsupported = matches!(extension.as_str(), "zip" | "exe" | "dll" | "db" | "sqlite" | "sqlite3" | "woff" | "woff2" | "ttf" | "mp4" | "mp3" | "doc" | "docx" | "xls" | "xlsx" | "ppt" | "pptx" | "bin" | "ico");
    let mut document = WorkspaceDocument { path: path_text(&relative(path, false)?)?, kind: "unsupported".into(), text: None, bytes: None, mime: mime.map(str::to_string), size: metadata.len(), modified: modified(&metadata) };
    if unsupported { return Ok(document); }
    let limit = if mime.is_some() { FILE_LIMIT } else { TEXT_LIMIT };
    if metadata.len() > limit { return Err("文本超过 2 MB 预览上限。".into()); }
    let mut bytes = Vec::with_capacity(metadata.len() as usize);
    file.by_ref().take(limit + 1).read_to_end(&mut bytes).map_err(|_| "无法读取文件内容。")?;
    if bytes.len() as u64 > limit { return Err("文件在读取期间超过预览上限。".into()); }
    if mime.is_some() {
        document.kind = if extension == "pdf" { "pdf" } else { "image" }.into();
        document.bytes = Some(bytes);
    } else if !bytes.contains(&0) {
        document.text = Some(String::from_utf8(bytes).map_err(|_| "此文件不是 UTF-8 文本，暂不支持预览。")?);
        document.kind = "text".into();
    }
    Ok(document)
}

fn git(root: &Path, args: &[&str]) -> Result<Output, String> {
    let mut command = Command::new("git");
    command.args(["--no-pager", "-c", "core.fsmonitor=false", "-c", "core.quotePath=false", "-c", "core.hooksPath=", "-C"]).arg(root).args(args)
        .env_clear().stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
    for key in ["SystemRoot", "PATH", "TEMP", "TMP"] { if let Some(value) = std::env::var_os(key) { command.env(key, value); } }
    command.env("GIT_CONFIG_NOSYSTEM", "1").env("GIT_CONFIG_GLOBAL", if cfg!(windows) { "NUL" } else { "/dev/null" }).env("GIT_OPTIONAL_LOCKS", "0").env("GIT_TERMINAL_PROMPT", "0");
    #[cfg(windows)] { use std::os::windows::process::CommandExt; command.creation_flags(0x08000000); }
    let mut child = command.spawn().map_err(|_| "Git 不可用，无法读取更改。")?;
    let stdout = child.stdout.take().ok_or("无法读取 Git 输出。")?;
    let stderr = child.stderr.take().ok_or("无法读取 Git 输出。")?;
    let (tx, rx) = mpsc::channel();
    let output_reader = thread::spawn(move || { let mut bytes = Vec::new(); let result = stdout.take(GIT_LIMIT as u64 + 1).read_to_end(&mut bytes); let _ = tx.send((result, bytes)); });
    let error_reader = thread::spawn(move || { let mut bytes = Vec::new(); let _ = stderr.take(65536).read_to_end(&mut bytes); bytes });
    let deadline = Instant::now() + Duration::from_secs(8);
    let mut captured = None;
    let mut failure = None;
    let status = loop {
        if let Ok((result, bytes)) = rx.try_recv() { if result.is_err() { failure = Some("无法读取 Git 输出。"); } if bytes.len() > GIT_LIMIT { failure = Some("更改超过 4 MB 读取上限，请缩小范围。"); } captured = Some(bytes); }
        if failure.is_some() || Instant::now() >= deadline { let _ = child.kill(); if failure.is_none() { failure = Some("Git 读取超时，请稍后重试。"); } break child.wait().map_err(|_| "无法结束 Git 读取。")?; }
        if let Some(status) = child.try_wait().map_err(|_| "无法查询 Git 读取状态。")? { break status; }
        thread::sleep(Duration::from_millis(10));
    };
    let _ = output_reader.join();
    let stderr = error_reader.join().unwrap_or_default();
    let stdout = captured.or_else(|| rx.recv().ok().map(|(_, bytes)| bytes)).unwrap_or_default();
    if stdout.len() > GIT_LIMIT { failure = Some("更改超过 4 MB 读取上限，请缩小范围。"); }
    if let Some(message) = failure { return Err(message.into()); }
    Ok(Output { status, stdout, stderr })
}

fn repository(root: &Path) -> Result<bool, String> {
    let output = git(root, &["rev-parse", "--show-toplevel"])?;
    if !output.status.success() { return Ok(false); }
    let value = String::from_utf8(output.stdout).map_err(|_| "Git 路径不是 UTF-8。")?;
    Ok(fs::canonicalize(value.trim()).map_err(|_| "Git 根目录不可用。")? == root_path(root)?)
}

pub fn changes(root: &Path) -> Result<ChangeSet, String> {
    if !repository(root)? { return Ok(ChangeSet { files: Vec::new(), repository: false, truncated: false }); }
    let output = git(root, &["status", "--porcelain=v1", "-z", "--untracked-files=normal", "--ignore-submodules=all"])?;
    if !output.status.success() { return Err("无法读取工作空间更改。".into()); }
    let mut records = output.stdout.split(|byte| *byte == 0).filter(|record| !record.is_empty());
    let mut files = Vec::new();
    let mut truncated = false;
    while let Some(record) = records.next() {
        if record.len() < 4 { return Err("Git 返回了无效的文件状态。".into()); }
        let status = std::str::from_utf8(&record[..2]).map_err(|_| "Git 状态无效。")?.to_string();
        let path = std::str::from_utf8(&record[3..]).map_err(|_| "Git 文件名不是 UTF-8。")?.to_string();
        let previous_path = if status.contains('R') || status.contains('C') { Some(String::from_utf8(records.next().ok_or("Git 重命名记录不完整。")?.to_vec()).map_err(|_| "Git 文件名不是 UTF-8。")?) } else { None };
        if files.len() >= ENTRY_LIMIT { truncated = true; break; }
        // Skip symlinks and malformed status paths rather than handing the UI an escape target.
        if resolve(root, &path, false, true).is_err() { continue; }
        files.push(FileChange { path, status: status.trim().to_string(), previous_path });
    }
    Ok(ChangeSet { files, repository: true, truncated })
}

pub fn diff(root: &Path, path: &str) -> Result<FileDiff, String> {
    resolve(root, path, false, true)?;
    if !repository(root)? { return Err("当前工作空间不是 Git 根目录，无法显示更改。".into()); }
    let output = git(root, &["diff", "--no-ext-diff", "--no-textconv", "--no-color", "HEAD", "--", path])?;
    let output = if output.status.success() { output } else { git(root, &["diff", "--no-ext-diff", "--no-textconv", "--no-color", "--", path])? };
    if !output.status.success() { return Err("无法读取此文件的更改。".into()); }
    let mut text = String::from_utf8(output.stdout).map_err(|_| "此更改不是 UTF-8 文本。")?;
    if text.is_empty() {
        let tracked = git(root, &["ls-files", "--error-unmatch", "--", path])?;
        if !tracked.status.success() {
            let document = read(root, path)?;
            if let Some(content) = document.text {
                let lines = content.lines().count();
                text = format!("--- /dev/null\n+++ b/{path}\n@@ -0,0 +1,{lines} @@\n");
                for line in content.lines() { text.push('+'); text.push_str(line); text.push('\n'); }
            } else { return Ok(FileDiff { text: "此文件为二进制文件。".into(), binary: true, truncated: false }); }
        }
    }
    let binary = text.contains("Binary files ") || text.contains("GIT binary patch");
    Ok(FileDiff { text, binary, truncated: false })
}

