import { useLayoutEffect, useRef, useState, type ReactNode } from "react";

/** Keep native summary keyboard semantics, and retain the subtree through collapse. */
export default function AnimatedDetails({ className, summary, summaryLabel, summaryTitle, summaryAction, scrollKey, initialExpanded = false, onExpandedChange, children, onInspect }: {
  className: string; summary: ReactNode; summaryLabel?: string; summaryTitle?: string; scrollKey?: string;
  summaryAction?: ReactNode;
  initialExpanded?: boolean; onExpandedChange?: (expanded: boolean) => void; children: ReactNode; onInspect: () => void;
}) {
  const [expanded, setExpanded] = useState(initialExpanded);
  const [present, setPresent] = useState(initialExpanded);
  const initial = useRef(initialExpanded);
  const animatedExpanded = useRef(initialExpanded);
  const desired = useRef(initialExpanded);
  const panel = useRef<HTMLDivElement>(null);

  // Depend only on user expansion. Polling must not restart animations or move scroll positions.
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !expanded);
    // A regrouped event restores its measured-open state without replaying an animation.
    if (animatedExpanded.current === expanded) return;
    animatedExpanded.current = expanded;
    const finish = () => {
      element.style.height = desired.current ? "auto" : "0px";
      element.style.opacity = desired.current ? "1" : "0";
      if (!desired.current) setPresent(false);
    };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    const height = element.getBoundingClientRect().height;
    const opacity = getComputedStyle(element).opacity;
    element.style.height = `${height}px`;
    element.style.opacity = opacity;
    // Establish the current rendered height before transitioning to the measured target.
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = expanded ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = expanded ? "1" : "0";
      const seconds = Number.parseFloat(getComputedStyle(element).getPropertyValue("--transition-duration-basic")) || .15;
      timeout = window.setTimeout(finish, seconds * 1000 + 50);
    });
    const transitioned = (event: TransitionEvent) => {
      if (event.target === element && event.propertyName === "height") finish();
    };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [expanded]);

  return <details className={`${className}${summaryAction ? " has-summary-action" : ""}`} data-scroll-key={scrollKey} open={present}>
    <summary aria-label={summaryLabel} aria-expanded={expanded} title={summaryTitle || undefined} onClick={(event) => {
      event.preventDefault();
      onInspect();
      desired.current = !desired.current;
      onExpandedChange?.(desired.current);
      setPresent(true);
      setExpanded(desired.current);
    }}>{summary}{summaryAction && <span className="detail-summary-action" onClick={(event) => event.stopPropagation()}>{summaryAction}</span>}</summary>
    <div ref={panel} className="detail-collapsible" style={{ height: initial.current ? "auto" : "0px", opacity: initial.current ? 1 : 0 }}>{children}</div>
  </details>;
}

import { useEffect, useLayoutEffect, useRef, type ReactNode, type RefObject } from "react";

/** A measured disclosure that stays mounted through polling and dismissal. */
export default function DisclosurePopover({ open, onClose, trigger, id, label, className, children }: {
  open: boolean; onClose: () => void; trigger: RefObject<HTMLButtonElement>;
  id: string; label: string; className: string; children: ReactNode;
}) {
  const panel = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const element = panel.current;
    if (!element) return;
    element.toggleAttribute("inert", !open);
    const finish = () => { element.style.height = open ? "auto" : "0px"; element.style.opacity = open ? "1" : "0"; };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    element.style.height = `${element.getBoundingClientRect().height}px`;
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = open ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = open ? "1" : "0";
      timeout = window.setTimeout(finish, 200);
    });
    const transitioned = (event: TransitionEvent) => { if (event.target === element && event.propertyName === "height") finish(); };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [open]);
  useEffect(() => {
    if (!open) return;
    const available = () => Array.from(panel.current?.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])') || []).filter((element) => element.getClientRects().length > 0 && !element.closest("[inert]"));
    const frame = requestAnimationFrame(() => (available()[0] || panel.current)?.focus({ preventScroll: true }));
    const dismiss = () => { onClose(); trigger.current?.focus(); };
    const pointer = (event: PointerEvent) => {
      if (event.target instanceof Node && !panel.current?.contains(event.target) && !trigger.current?.contains(event.target)) onClose();
    };
    const focus = (event: FocusEvent) => {
      if (event.target instanceof Node && !panel.current?.contains(event.target) && !trigger.current?.contains(event.target)) onClose();
    };
    const key = (event: KeyboardEvent) => {
      if (event.key === "Escape") { event.preventDefault(); dismiss(); return; }
      if (!(event.target instanceof HTMLElement) || !panel.current?.contains(event.target)) return;
      const items = available(), index = items.indexOf(event.target);
      if (event.key === "Tab" && ((event.shiftKey && index <= 0) || (!event.shiftKey && index === items.length - 1))) {
        if (event.shiftKey) { event.preventDefault(); trigger.current?.focus({ preventScroll: true }); }
        else {
          const all = Array.from(document.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])')).filter((element) => element.getClientRects().length > 0 && !element.closest("[inert]") && !panel.current?.contains(element));
          const next = trigger.current ? all[all.indexOf(trigger.current) + 1] : undefined;
          if (next) { event.preventDefault(); next.focus({ preventScroll: true }); }
        }
        onClose();
      } else if (!["INPUT", "TEXTAREA", "SELECT"].includes(event.target.tagName) && ["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key) && items.length) {
        event.preventDefault();
        const next = event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : event.key === "ArrowDown" ? (index + 1) % items.length : (index - 1 + items.length) % items.length;
        items[next].focus({ preventScroll: true });
      }
    };
    document.addEventListener("pointerdown", pointer);
    document.addEventListener("focusin", focus);
    document.addEventListener("keydown", key);
    return () => { cancelAnimationFrame(frame); document.removeEventListener("pointerdown", pointer); document.removeEventListener("focusin", focus); document.removeEventListener("keydown", key); };
  }, [open, onClose, trigger]);
  return <div ref={panel} id={id} className={`disclosure-popover ${className}`} role="dialog" tabIndex={-1} aria-label={label} aria-hidden={!open}>
    <div className="popover-surface">{children}</div>
  </div>;
}

import { useCallback, useEffect, useRef, useState, type KeyboardEvent, type RefObject } from "react";
import DisclosurePopover from "./DisclosurePopover";

export default function ConversationComposer({ inputRef, value, onChange, onKeyDown, onSend, onConfigure, disabled, sending, workspace, workspaceName, native, model, provider, status, visible, error, requestId, fileChanges, onOpenChanges }: {
  inputRef: RefObject<HTMLTextAreaElement>; value: string; onChange: (value: string) => void;
  onKeyDown: (event: KeyboardEvent<HTMLTextAreaElement>) => void; onSend: () => void;
  onConfigure: (setting: "environment" | "models") => void;
  disabled: boolean; sending: boolean; workspace: string; workspaceName: string; native: boolean;
  model: string; provider: string; status: string; visible: boolean; error: string; requestId?: string;
  fileChanges?: number; onOpenChanges?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const close = useCallback(() => setOpen(false), []);
  useEffect(() => { if (!visible) setOpen(false); }, [visible]);
  const configure = (setting: "environment" | "models") => { setOpen(false); onConfigure(setting); };
  return <footer className="composer-wrap"><div className="composer-stack">
    {onOpenChanges && typeof fileChanges === "number" && fileChanges > 0 && <div className="composer-changes"><button type="button" title="已加载对话中成功写入的真实文件记录；不代表当前 Git 变更总数。" onClick={onOpenChanges}><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="M4 2.5h5l3 3v8H4v-11Zm5 0v3h3M6 9h4M8 7v4" /></svg>{fileChanges} 个文件已更改</button></div>}
