    <div className="preview-toolbar"><span className="preview-breadcrumb" title={active || workspaceName}>{source === imported ? importName : workspaceName}<span>›</span><strong>{active || "文件"}</strong></span>{active && <div className="preview-view-actions">{changed && <button type="button" aria-pressed={mode === "diff"} onClick={() => setModes((old) => ({ ...old, [active]: mode === "diff" ? "preview" : "diff" }))}>显示更改</button>}{document?.kind === "text" && /\.md(?:own)?$/i.test(active) && <button type="button" aria-pressed={mode === "source"} onClick={() => setModes((old) => ({ ...old, [active]: mode === "source" ? "preview" : "source" }))}>{mode === "source" ? "预览" : "查看源代码"}</button>}{document?.text !== undefined && <button type="button" aria-label="复制文件内容" title="复制内容" onClick={() => void navigator.clipboard.writeText(document.text || "").then(() => report("已复制文件内容"), () => report("无法复制，请手动选择。"))}>复制</button>}<button type="button" aria-label="重新读取文件" title="重新读取" onClick={() => { read(active, true); setRefresh((value) => value + 1); }}>↻</button></div>}</div>
    {feedback && <span className="preview-feedback" role="status">{feedback}</span>}
    <div className="preview-content"><div className="preview-document">{tabs.map((path, index) => <div className="file-tab-panel" key={path} id={`file-pane-${index}`} role="tabpanel" aria-labelledby={`file-tab-${index}`} hidden={active !== path}><DocumentPane state={documents[path] || { loading: !!source, error: source ? "" : "请先选择此文件所在的目录。" }} path={path} mode={modes[path] || "preview"} source={source} native={native} refresh={refresh} visible={active === path} onOpen={openFile} /></div>)}{!active && <div className="preview-empty"><FileIcon folder /><h3>工作空间文件</h3><p>{source ? "从文件树选择文件，或点击对话中的文件引用。" : "在浏览器中选择本地目录或文件进行只读预览。"}</p>{!native && <div className="button-row"><button type="button" className="button" onClick={() => directoryInput.current?.click()}>选择目录</button><button type="button" className="button" onClick={() => filesInput.current?.click()}>选择文件</button></div>}</div>}</div>
      <div className="preview-file-tree" hidden={!tree}><div className="file-tree-search"><input aria-label="筛选已加载文件" placeholder="筛选已加载文件…" value={query} onChange={(event) => setQuery(event.target.value)} /></div><div className="file-tree-scopes"><button type="button" aria-pressed={scope === "files"} onClick={() => setScope("files")}>所有文件</button><button type="button" aria-pressed={scope === "changes"} onClick={() => setScope("changes")}>已更改{changes.repository ? ` ${changes.files.length}` : ""}</button>{scope === "conversation" && <span>对话记录</span>}<button type="button" aria-label="刷新文件树" title="刷新文件树与更改" onClick={() => setRefresh((value) => value + 1)}>↻</button></div><div className="file-tree-scroll">{scope === "files" ? source ? <Directory path="" source={source} active={active} onOpen={openFile} query={query.toLocaleLowerCase().trim()} refresh={refresh} /> : <p className="tree-notice">尚未选择文件。</p> : <>{changesError && <p className="tree-notice error" role="alert">{changesError}</p>}<p className="file-tree-caption">{scope === "conversation" ? "已加载对话中记录的文件；差异来自当前 Git。" : changes.repository ? "当前工作空间 · Git 工作树与暂存区" : "当前文件来源没有 Git 变更记录。"}</p>{displayedChanges.filter((file) => file.path.toLocaleLowerCase().includes(query.toLocaleLowerCase().trim())).map((file) => <button type="button" key={file.path} className={`file-tree-row changed-file${active === file.path ? " selected" : ""}`} title={file.path} onClick={() => { openFile(file.path); if (changes.files.some((change) => change.path === file.path)) setModes((old) => ({ ...old, [file.path]: "diff" })); }}><span className="file-change-status">{file.status}</span><span>{file.path}</span>{file.added !== undefined && <small className="file-added">+{file.added}</small>}{file.removed !== undefined && <small className="file-removed">−{file.removed}</small>}</button>)}{changes.truncated && <p className="tree-notice">变更较多，仅显示已读取部分。</p>}</>}</div>{!native && <button type="button" className="file-import-button" onClick={() => directoryInput.current?.click()}>选择本地目录…</button>}</div>
    </div><input ref={filesInput} type="file" multiple hidden aria-label="选择预览文件" onChange={(event) => { chooseFiles(event.target.files); event.currentTarget.value = ""; }} /><input ref={directoryInput} type="file" multiple hidden aria-label="选择预览目录" onChange={(event) => { chooseFiles(event.target.files); event.currentTarget.value = ""; }} />
  </aside>;
}

export function PreviewDivider({ width, onResize }: { width: number; onResize: (width: number) => void }) {
  const drag = useRef<{ x: number; width: number } | null>(null);
  const clamp = (value: number) => Math.min(76, Math.max(34, value));
  const move = (event: ReactPointerEvent<HTMLDivElement>) => { if (!drag.current) return; const total = event.currentTarget.parentElement?.clientWidth || 1; onResize(clamp(drag.current.width + (drag.current.x - event.clientX) / total * 100)); };
  return <div className="preview-divider" role="separator" aria-label="调整文件预览宽度" aria-orientation="vertical" aria-valuemin={34} aria-valuemax={76} aria-valuenow={Math.round(width)} tabIndex={0} onPointerDown={(event) => { drag.current = { x: event.clientX, width }; event.currentTarget.setPointerCapture(event.pointerId); }} onPointerMove={move} onPointerUp={(event) => { drag.current = null; event.currentTarget.releasePointerCapture(event.pointerId); }} onPointerCancel={() => { drag.current = null; }} onKeyDown={(event) => { if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) { event.preventDefault(); onResize(event.key === "Home" ? 34 : event.key === "End" ? 76 : clamp(width + (event.key === "ArrowLeft" ? 2 : -2))); } }} />;
}
import { invoke } from "@tauri-apps/api/core";

export interface WorkspaceFile { path: string; name: string; directory: boolean; size?: number; modified?: number }
export interface FileChange { path: string; status: string; added?: number; removed?: number; previousPath?: string }
export interface ChangeSet { files: FileChange[]; repository: boolean; truncated?: boolean }
export interface WorkspaceDocument { path: string; kind: "text" | "pdf" | "image" | "unsupported"; text?: string; bytes?: number[]; mime?: string; size: number; modified?: number }
export interface FileSource {
  list(path: string): Promise<WorkspaceFile[]>;
  read(path: string): Promise<WorkspaceDocument>;
  changes(): Promise<ChangeSet>;
  diff(path: string): Promise<{ text: string; binary?: boolean; truncated?: boolean }>;
}
const MAX_FILE = 24 * 1024 * 1024;
const TEXT_LIMIT = 2 * 1024 * 1024;
export function relativeFilePath(input: string): string {
  const path = input.replace(/\\/g, "/").replace(/^\.\//, "");
  if (!path || path.startsWith("/") || /^[A-Za-z]:/.test(path) || path.split("/").some((part) => part === ".." || part === "" || part.includes(":")) || /[\x00-\x1f]/.test(path)) throw new Error("文件路径不在当前工作空间中。");
  return path;
}
export function fileKind(path: string): WorkspaceDocument["kind"] {
  if (/\.pdf$/i.test(path)) return "pdf";
  if (/\.(png|jpg|jpeg|gif|webp|avif|bmp)$/i.test(path)) return "image";
  if (/\.(zip|exe|dll|db|sqlite3?|woff2?|ttf|mp4|mp3|docx?|xlsx?|pptx?|bin|ico)$/i.test(path)) return "unsupported";
  return "text";
}
export function nativeFileSource(): FileSource {
  return {
    list: (path) => invoke("workspace_files_list", { path }),
    read: (path) => invoke("workspace_file_read", { path: relativeFilePath(path) }),
    changes: () => invoke("workspace_changes"),
    diff: (path) => invoke("workspace_file_diff", { path: relativeFilePath(path) }),
  };
}
export function importedFileSource(input: File[]): FileSource {
  const directory = input[0]?.webkitRelativePath.split("/")[0];
  const sharedRoot = directory && input.every((file) => file.webkitRelativePath.startsWith(`${directory}/`)) ? `${directory}/` : "";
  const files = new Map(input.map((file) => [relativeFilePath(sharedRoot ? file.webkitRelativePath.slice(sharedRoot.length) : file.webkitRelativePath || file.name), file]));
  return {
    async list(directory) {
      const prefix = directory ? `${relativeFilePath(directory)}/` : "";
      const entries = new Map<string, WorkspaceFile>();
      for (const [path, file] of files) {
        if (!path.startsWith(prefix)) continue;
        const suffix = path.slice(prefix.length), name = suffix.split("/")[0], child = prefix + name;
        if (!entries.has(child)) entries.set(child, { path: child, name, directory: suffix.includes("/"), size: file.size, modified: file.lastModified });
      }
      return [...entries.values()].sort((a, b) => Number(b.directory) - Number(a.directory) || a.name.localeCompare(b.name));
    },
    async read(value) {
      const path = relativeFilePath(value), file = files.get(path);
      if (!file) throw new Error("此文件未在选择的文件中，请选择所在目录或文件。");
      if (file.size > MAX_FILE) throw new Error("文件超过 24 MB 预览上限。");
      const kind = fileKind(path);
      if (kind === "text") {
        if (file.size > TEXT_LIMIT) throw new Error("文本超过 2 MB 预览上限。");
        const bytes = await file.arrayBuffer();
        let text: string;
        try { text = new TextDecoder("utf-8", { fatal: true }).decode(bytes); } catch { throw new Error("此文件不是 UTF-8 文本，暂不支持预览。"); }
        if (text.includes("\0")) return { path, kind: "unsupported", size: file.size };
        return { path, kind, text, size: file.size, modified: file.lastModified };
      }
      return { path, kind, bytes: kind === "unsupported" ? undefined : [...new Uint8Array(await file.arrayBuffer())], mime: kind === "pdf" ? "application/pdf" : file.type, size: file.size, modified: file.lastModified };
    },
    async changes() { return { files: [], repository: false }; },
    async diff() { throw new Error("导入文件不包含 Git 历史，无法显示更改。"); },
  };
}

//! Bounded, read-only file inspection scoped to the Core host's immutable workspace root.
use serde::Serialize;
use std::fs::{self, File};
use std::io::Read;
use std::path::{Component, Path, PathBuf};
use std::process::{Command, Output, Stdio};
use std::sync::mpsc;
use std::thread;
use std::time::{Duration, Instant, UNIX_EPOCH};

const FILE_LIMIT: u64 = 24 * 1024 * 1024;
const TEXT_LIMIT: u64 = 2 * 1024 * 1024;
const GIT_LIMIT: usize = 4 * 1024 * 1024;
const ENTRY_LIMIT: usize = 5000;

#[derive(Serialize)]
pub struct WorkspaceFile {
    path: String,
    name: String,
    directory: bool,
    size: u64,
    modified: Option<u64>,
}
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FileChange {
    path: String,
    status: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    previous_path: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    added: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    removed: Option<u64>,
}
#[derive(Serialize)]
pub struct ChangeSet {
    files: Vec<FileChange>,
    repository: bool,
    truncated: bool,
}
#[derive(Serialize)]
pub struct WorkspaceDocument {
    path: String,
    kind: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    text: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    bytes: Option<Vec<u8>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    mime: Option<String>,
    size: u64,
    modified: Option<u64>,
}
#[derive(Serialize)]
pub struct FileDiff {
    text: String,
    binary: bool,
    truncated: bool,
}

fn relative(value: &str, allow_empty: bool) -> Result<PathBuf, String> {
    if value.is_empty() && allow_empty {
        return Ok(PathBuf::new());
    }
    if value.is_empty() || value.len() > 4096 || value.chars().any(|c| c.is_control() || c == ':') {
        return Err("文件路径不在当前工作空间中。".into());
    }
    let normalized = value.replace('\\', "/");
    if normalized
        .split('/')
        .any(|part| part.is_empty() || part == "." || part == "..")
    {
        return Err("文件路径不在当前工作空间中。".into());
    }
    let path = PathBuf::from(normalized);
    if path
        .components()
        .any(|part| !matches!(part, Component::Normal(_)))
    {
        return Err("文件路径不在当前工作空间中。".into());
    }
    Ok(path)
}

fn root_path(root: &Path) -> Result<PathBuf, String> {
    fs::canonicalize(root).map_err(|_| "当前工作空间目录不可用。".into())
}

fn is_link(metadata: &fs::Metadata) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        metadata.file_attributes() & 0x400 != 0
    }
    #[cfg(not(windows))]
    metadata.file_type().is_symlink()
}

fn resolve(
    root: &Path,
    value: &str,
    allow_empty: bool,
    allow_missing: bool,
) -> Result<PathBuf, String> {
    let relative = relative(value, allow_empty)?;
    let canonical_root = root_path(root)?;
    let mut candidate = canonical_root.clone();
    for part in relative.components() {
        candidate.push(part.as_os_str());
        match fs::symlink_metadata(&candidate) {
            Ok(metadata) if is_link(&metadata) => {
                return Err("不能预览符号链接或重解析目录。".into())
            }
            Ok(_) => {}
            Err(error) if allow_missing && error.kind() == std::io::ErrorKind::NotFound => {}
            Err(_) => return Err("文件或目录不可用。".into()),
        }
    }
    let existing = if candidate.exists() {
        candidate.as_path()
    } else {
        candidate
            .ancestors()
            .find(|path| path.exists())
            .ok_or("文件路径不可用。")?
    };
    if !fs::canonicalize(existing)
        .map_err(|_| "文件路径不可用。")?
        .starts_with(&canonical_root)
    {
        return Err("文件路径不在当前工作空间中。".into());
    }
    Ok(candidate)
}

fn modified(metadata: &fs::Metadata) -> Option<u64> {
    metadata
        .modified()
        .ok()?
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|value| value.as_millis() as u64)
}

fn path_text(path: &Path) -> Result<String, String> {
    path.to_str()
        .map(|value| value.replace('\\', "/"))
        .ok_or("此文件名不是有效 Unicode。".into())
}

pub fn list(root: &Path, path: &str) -> Result<Vec<WorkspaceFile>, String> {
    let directory = resolve(root, path, true, false)?;
    if !directory.is_dir() {
        return Err("此路径不是目录。".into());
    }
    let mut files = Vec::new();
    let canonical_root = root_path(root)?;
    for entry in fs::read_dir(directory).map_err(|_| "无法读取工作空间目录。")? {
        let entry = entry.map_err(|_| "无法读取目录项目。")?;
        let metadata = fs::symlink_metadata(entry.path()).map_err(|_| "无法读取文件信息。")?;
        if is_link(&metadata) {
            continue;
        }
        if files.len() >= ENTRY_LIMIT {
            return Err("此目录超过 5000 项，请打开更具体的子目录。".into());
        }
        let relative = path_text(
            entry
                .path()
                .strip_prefix(&canonical_root)
                .map_err(|_| "目录越过工作空间边界。")?,
        )?;
        files.push(WorkspaceFile {
            path: relative,
            name: entry.file_name().to_string_lossy().into_owned(),
            directory: metadata.is_dir(),
            size: metadata.len(),
            modified: modified(&metadata),
        });
    }
    files.sort_by(|a, b| {
        b.directory
            .cmp(&a.directory)
            .then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase()))
    });
    Ok(files)
}

fn opened_in_workspace(file: &File, root: &Path) -> Result<(), String> {
    #[cfg(windows)]
    {
        use std::ffi::OsString;
        use std::os::windows::ffi::OsStringExt;
        use std::os::windows::io::AsRawHandle;
        #[link(name = "kernel32")]
        extern "system" {
            fn GetFinalPathNameByHandleW(
                handle: *mut std::ffi::c_void,
                path: *mut u16,
                size: u32,
                flags: u32,
            ) -> u32;
        }
        let mut buffer = vec![0_u16; 32768];
        let length = unsafe {
            GetFinalPathNameByHandleW(
                file.as_raw_handle(),
                buffer.as_mut_ptr(),
                buffer.len() as u32,
                0,
            )
        } as usize;
        if length == 0 || length >= buffer.len() {
            return Err("无法验证文件的工作空间范围。".into());
        }
        let final_path = PathBuf::from(OsString::from_wide(&buffer[..length]));
        if !final_path.starts_with(root_path(root)?) {
            return Err("文件路径不在当前工作空间中。".into());
        }
    }
    #[cfg(not(windows))]
    {
        let _ = (file, root);
    }
    Ok(())
}

pub fn read(root: &Path, path: &str) -> Result<WorkspaceDocument, String> {
    let resolved = resolve(root, path, false, false)?;
    let mut file = File::open(&resolved).map_err(|_| "无法打开文件。")?;
    opened_in_workspace(&file, root)?;
    let metadata = file.metadata().map_err(|_| "无法读取文件信息。")?;
    if !metadata.is_file() {
        return Err("此路径不是普通文件。".into());
    }
    if metadata.len() > FILE_LIMIT {
        return Err("文件超过 24 MB 预览上限。".into());
    }
    let extension = resolved
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    let mime = match extension.as_str() {
        "pdf" => Some("application/pdf"),
        "png" => Some("image/png"),
        "jpg" | "jpeg" => Some("image/jpeg"),
        "gif" => Some("image/gif"),
        "webp" => Some("image/webp"),
        "avif" => Some("image/avif"),
        "bmp" => Some("image/bmp"),
        _ => None,
    };
    let unsupported = matches!(
        extension.as_str(),
        "zip"
            | "exe"
            | "dll"
            | "db"
            | "sqlite"
            | "sqlite3"
            | "woff"
            | "woff2"
            | "ttf"
            | "mp4"
            | "mp3"
            | "doc"
            | "docx"
            | "xls"
            | "xlsx"
            | "ppt"
            | "pptx"
            | "bin"
            | "ico"
    );
    let mut document = WorkspaceDocument {
        path: path_text(&relative(path, false)?)?,
        kind: "unsupported".into(),
        text: None,
        bytes: None,
        mime: mime.map(str::to_string),
        size: metadata.len(),
        modified: modified(&metadata),
    };
    if unsupported {
        return Ok(document);
    }
    let limit = if mime.is_some() {
        FILE_LIMIT
    } else {
        TEXT_LIMIT
    };
    if metadata.len() > limit {
        return Err("文本超过 2 MB 预览上限。".into());
    }
    let mut bytes = Vec::with_capacity(metadata.len() as usize);
    file.by_ref()
        .take(limit + 1)
        .read_to_end(&mut bytes)
        .map_err(|_| "无法读取文件内容。")?;
    if bytes.len() as u64 > limit {
        return Err("文件在读取期间超过预览上限。".into());
    }
    if mime.is_some() {
        document.kind = if extension == "pdf" { "pdf" } else { "image" }.into();
        document.bytes = Some(bytes);
    } else if !bytes.contains(&0) {
        document.text =
            Some(String::from_utf8(bytes).map_err(|_| "此文件不是 UTF-8 文本，暂不支持预览。")?);
        document.kind = "text".into();
    }
    Ok(document)
}

fn git(root: &Path, args: &[&str]) -> Result<Output, String> {
    let mut command = Command::new("git");
    command
        .args([
            "--no-pager",
            "--literal-pathspecs",
            "-c",
            "core.fsmonitor=false",
            "-c",
            "core.quotePath=false",
            "-c",
            "core.hooksPath=",
            "-C",
        ])
        .arg(root)
    }
    Ok(Output {
        status,
        stdout,
        stderr,
    })
}

fn repository_prefix(root: &Path) -> Result<Option<String>, String> {
    let output = git(root, &["rev-parse", "--show-toplevel"])?;
    if !output.status.success() {
        return Ok(None);
    }
    let value = String::from_utf8(output.stdout).map_err(|_| "Git 路径不是 UTF-8。")?;
    let repository = fs::canonicalize(value.trim()).map_err(|_| "Git 根目录不可用。")?;
    let workspace = root_path(root)?;
    let prefix = workspace
        .strip_prefix(repository)
        .map_err(|_| "Git 目录越过工作空间边界。")?;
    Ok(Some(path_text(prefix)?))
}

fn scoped_git_path(prefix: &str, path: &str) -> Option<String> {
    let path = if prefix.is_empty() {
        path
    } else {
        path.strip_prefix(prefix)?.strip_prefix('/')?
    };
    relative(path, false).ok()?;
    Some(path.to_string())
}

pub fn changes(root: &Path) -> Result<ChangeSet, String> {
    let Some(prefix) = repository_prefix(root)? else {
        return Ok(ChangeSet {
            files: Vec::new(),
            repository: false,
            truncated: false,
        });
    };
    let output = git(
        root,
        &[
            "status",
            "--porcelain=v1",
            "-z",
            "--untracked-files=all",
            "--ignore-submodules=all",
            "--",
            ".",
        ],
    )?;
    if !output.status.success() {
        return Err("无法读取工作空间更改。".into());
    }
    let mut records = output
        .stdout
        .split(|byte| *byte == 0)
        .filter(|record| !record.is_empty());
    let mut files = Vec::new();
    let mut truncated = false;
    while let Some(record) = records.next() {
        if record.len() < 4 {
            return Err("Git 返回了无效的文件状态。".into());
        }
        let mut status = std::str::from_utf8(&record[..2])
            .map_err(|_| "Git 状态无效。")?
            .to_string();
        let repository_path = std::str::from_utf8(&record[3..])
            .map_err(|_| "Git 文件名不是 UTF-8。")?
            .to_string();
        let had_previous = status.contains('R') || status.contains('C');
        let mut previous_path = if had_previous {
            let previous = std::str::from_utf8(records.next().ok_or("Git 重命名记录不完整。")?)
                .map_err(|_| "Git 文件名不是 UTF-8。")?;
            scoped_git_path(&prefix, previous)
        } else {
            None
        };
        let path = match (
            scoped_git_path(&prefix, &repository_path),
            previous_path.as_ref(),
        ) {
            (Some(path), _) => {
                if had_previous && previous_path.is_none() && !prefix.is_empty() {
                    status = "A".into();
                }
                path
            }
            (None, Some(previous)) => {
                let path = previous.clone();
                previous_path = None;
                status = "D".into();
                path
            }
            (None, None) => continue,
        };
        if files.len() >= ENTRY_LIMIT {
            truncated = true;
            break;
        }
        // Skip symlinks and malformed status paths rather than handing the UI an escape target.
        if resolve(root, &path, false, true).is_err() {
            continue;
        }
        files.push(FileChange {
            path,
            status: status.trim().to_string(),
            previous_path,
            added: None,
            removed: None,
        });
    }
    if let Ok(stats) = git(
        root,
        &[
            "diff",
            "--numstat",
            "-z",
            "--no-ext-diff",
            "--no-textconv",
            "--relative",
            "HEAD",
            "--",
            ".",
        ],
    ) {
        if stats.status.success() {
            let mut records = stats
                .stdout
                .split(|byte| *byte == 0)
                .filter(|record| !record.is_empty());
            while let Some(record) = records.next() {
                let mut fields = record.splitn(3, |byte| *byte == b'\t');
                let added = fields
                    .next()
                    .and_then(|value| std::str::from_utf8(value).ok())
                    .and_then(|value| value.parse::<u64>().ok());
                let removed = fields
                    .next()
                    .and_then(|value| std::str::from_utf8(value).ok())
                    .and_then(|value| value.parse::<u64>().ok());
                let path = fields.next().unwrap_or_default();
                let path = if path.is_empty() {
                    let _previous = records.next();
                    records.next().unwrap_or_default()
                } else {
                    path
                };
                if let Ok(path) = std::str::from_utf8(path) {
                    if let Some(file) = files.iter_mut().find(|file| file.path == path) {
                        file.added = added;
                        file.removed = removed;
                    }
                }
            }
        }
    }
    Ok(ChangeSet {
        files,
        repository: true,
        truncated,
    })
}

fn new_file_diff(root: &Path, path: &str) -> Result<FileDiff, String> {
    let document = match read(root, path) {
        Ok(document) => document,
        Err(error) if error == "此文件不是 UTF-8 文本，暂不支持预览。" => {
            return Ok(FileDiff {
                text: String::new(),
                binary: true,
                truncated: false,
            });
        }
        Err(error) => return Err(error),
    };
    let Some(content) = document.text else {
        return Ok(FileDiff {
            text: String::new(),
            binary: true,
            truncated: false,
        });
    };
    let lines = content.split_terminator('\n').count();
    let mut text = format!(
        "diff --git a/{path} b/{path}\nnew file mode 100644\n--- /dev/null\n+++ b/{path}\n"
    );
    if lines > 0 {
        text.push_str(&format!("@@ -0,0 +1,{lines} @@\n"));
        for line in content.split_terminator('\n') {
            text.push('+');
            text.push_str(line);
            text.push('\n');
        }
        if !content.ends_with('\n') {
            text.push_str("\\ No newline at end of file\n");
        }
    }
    Ok(FileDiff {
        text,
        binary: false,
        truncated: false,
    })
}

pub fn diff(root: &Path, path: &str) -> Result<FileDiff, String> {
    resolve(root, path, false, true)?;
    if repository_prefix(root)?.is_none() {
        return Err("当前工作空间不在 Git 仓库中，无法显示更改。".into());
    }
    let head = git(root, &["rev-parse", "--verify", "HEAD"])?;
    if !head.status.success() {
        return new_file_diff(root, path);
    }
    let output = git(
        root,
        &[
            "diff",
            "--no-ext-diff",
            "--no-textconv",
            "--no-color",
            "--relative",
            "HEAD",
            "--",
            path,
        ],
    )?;
    let output = if output.status.success() {
        output
    } else {
        git(
            root,
            &[
                "diff",
                "--no-ext-diff",
                "--no-textconv",
                "--no-color",
                "--relative",
                "--",
                path,
            ],
        )?
    };
    if !output.status.success() {
        return Err("无法读取此文件的更改。".into());
    }
    let text = String::from_utf8(output.stdout).map_err(|_| "此更改不是 UTF-8 文本。")?;
    if text.is_empty() {
        let tracked = git(root, &["ls-files", "--error-unmatch", "--", path])?;
        if !tracked.status.success() {
            return new_file_diff(root, path);
        }
    }
    let binary = text.contains("Binary files ") || text.contains("GIT binary patch");
    Ok(FileDiff {
        text,
        binary,
        truncated: false,
    })

